import { z } from 'zod';
import { env } from 'cloudflare:workers';

// The one static env import for server-only modules. `Cloudflare.Env` is
// generated by `wrangler types` from wrangler.jsonc (bindings) plus the
// local secret names; optional secrets that may not exist on every install
// are declared here instead of being cast at each call site.
export type WorkerEnv = Cloudflare.Env & {
  BETTER_AUTH_SECRET?: string;
  BETTER_AUTH_URL?: string;
  STRIPE_SECRET_KEY?: string;
  STRIPE_WEBHOOK_SECRET?: string;
  TURNSTILE_SECRET_KEY?: string;
  OWNER_EMAIL?: string;
  DEV_TRUSTED_ORIGINS?: string;
  PUBLIC_MEDIA?: R2Bucket;
  MEDIA_ZONE_ID?: string;
  MEDIA_PURGE_TOKEN?: string;
};

export const workerEnv: WorkerEnv = env;

export const runtimeConfigSchema = z.object({
  BETTER_AUTH_SECRET: z.string().min(32).optional(),
  BETTER_AUTH_URL: z.string().optional(),
  DEV_TRUSTED_ORIGINS: z.string().optional(),
  STRIPE_SECRET_KEY: z.string().startsWith('sk_').optional(),
  STRIPE_WEBHOOK_SECRET: z.string().startsWith('whsec_').optional(),
  TURNSTILE_SECRET_KEY: z.string().optional(),
  OWNER_EMAIL: z.string().optional(),
  MEDIA_ZONE_ID: z
    .string()
    .regex(/^[a-f0-9]{32}$/i)
    .optional(),
  MEDIA_PURGE_TOKEN: z.string().min(1).optional(),
});
export { exactDevOrigins } from './origins';
